SET NAMES utf8mb4;

INSERT INTO `service`
  (`token`, `service_name`, `service_img`, `short_description`, `description`,
   `card1_title`, `card1_description`, `card2_title`, `card2_description`,
   `process_steps`, `faqs`, `status`, `delete_status`, `created_by`)
SELECT
  'genset-battery-service',
  'Genset Battery Initialization, Service & Jump Starter',
  'themes/images/service-image-11.jpg',
  'Genset battery initialization, maintenance and jump-start assistance in Coimbatore to keep your generator ready when backup power is needed. Service for offices, commercial buildings, industrial units and homes, Monday to Saturday, 9AM to 10PM.',
  'A reliable battery is essential for starting a generator when backup power is needed. Kiara Battery Clinic provides genset battery initialization, service and jump-start assistance in Coimbatore and nearby areas including Ooty, Kotagiri, Pollachi and Tiruppur, Monday to Saturday, 9AM to 10PM. Our service addresses common generator battery issues such as insufficient charge, starting difficulties and routine battery maintenance.\n\nWe assist with genset battery initialization, battery condition checks, terminal inspection, maintenance and jump-start support where appropriate. Whether your generator is used in a commercial building, industrial facility, office, residential property or other location, proper battery care supports dependable generator starting and backup power readiness.\n\nOur process focuses on identifying battery-related issues, checking compatibility and applying suitable service procedures according to the generator manufacturer''s recommendations. If the battery is damaged, cannot hold a charge or needs replacement, further inspection helps determine the right solution - with genuine Exide, Amaron, Okaya and Luminous batteries available.\n\nKeep your generator battery in better working condition with professional genset battery service designed to support reliable starting and reduce unexpected interruptions. Call or WhatsApp +91 90038 11107 to book a visit.',
  'Genset Battery Initialization & Maintenance',
  'Prepare your generator battery for reliable starting with appropriate initialization, battery condition checks, terminal inspection and maintenance. Our service helps identify common battery issues and supports generator readiness through proper battery care.',
  'Generator Battery Jump-Start Assistance',
  'Experiencing generator starting problems due to a discharged battery? Our genset jump-start assistance helps restore starting capability when conditions permit. We use suitable equipment and recommended safety procedures to protect the battery and generator electrical system.',
  'Service request - contact our team and describe your generator battery or starting issue.\nGenerator details - share the genset make, model, battery specifications and service location.\nBattery inspection - check the battery condition, terminals, connections and relevant starting-system components.\nBattery initialization - perform the required initialization or setup according to the generator manufacturer specifications, where applicable.\nBattery service or jump start - carry out suitable battery maintenance, charging support or jump-start assistance based on the inspection results.\nStarting system check - check the generator starting operation and identify any remaining battery-related concerns.\nService recommendations - advise whether further testing, charging, repair or battery replacement is required.',
  '[{"question":"What is genset battery initialization?","answer":"Genset battery initialization means preparing or setting up the generator battery and its associated system according to the manufacturer requirements. The exact procedure depends on the generator model, battery type and control system."},{"question":"Why does my generator battery need servicing?","answer":"Generator batteries can lose charge, develop corroded terminals, suffer connection problems or deteriorate over time. Regular inspection and maintenance help identify these issues before they affect generator starting."},{"question":"Do you provide jump-start assistance for generators in Coimbatore?","answer":"Yes, where the generator battery system is compatible. The battery voltage, battery type and the generator manufacturer instructions are checked before attempting a jump start. Call or WhatsApp +91 90038 11107 to confirm availability for your genset."},{"question":"How often should a genset battery be checked?","answer":"It depends on the generator manufacturer maintenance schedule, battery type, operating conditions and standby requirements. Regular checks help identify low charge, corrosion and other potential problems."},{"question":"Can a generator run with a weak battery?","answer":"A generator may fail to start if its battery cannot supply enough power to the starting system. Even if a weak battery still starts the generator occasionally, it should be tested to find out whether charging or replacement is needed."},{"question":"Does genset battery servicing include battery replacement?","answer":"Replacement is recommended when inspection shows the battery is damaged, deteriorated or unable to hold an adequate charge. Replacement availability and charges should be confirmed with our service team."},{"question":"What information is required to request genset battery service?","answer":"Share the generator make and model, battery voltage and type if known, details of the starting issue and your service location. These details help determine the right service requirements."},{"question":"Can regular genset battery maintenance prevent starting problems?","answer":"Regular maintenance helps find charge issues, loose connections and terminal corrosion before they cause starting difficulties. It cannot prevent every failure, so periodic testing and following the manufacturer maintenance recommendations remain important."},{"question":"What are your genset battery service hours and coverage?","answer":"Our service hours are Monday to Saturday, 9AM to 10PM, covering Coimbatore (Tatabad, Gandhipuram, RS Puram, Peelamedu, Saravanampatti) and, on request, Ooty, Kotagiri, Pollachi and Tiruppur."}]',
  'active',
  0,
  0
FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `service` WHERE `token` = 'genset-battery-service');
